import sys

def main():
    # Read the first line and strip any whitespace
    T = sys.stdin.readline().strip()

    # Read the second line and convert to integer
    E = int(sys.stdin.readline().strip())

    # Determine the action based on traffic light and emergency vehicle status
    if T == 'R':
        if E == 1:
            print("ALLOW EMERGENCY")
        else:
            print("STOP")
    elif T == 'Y':
        print("PREPARE TO STOP")
    elif T == 'G':
        if E == 1:
            print("CLEAR THE WAY")
        else:
            print("PROCEED")

if __name__ == "__main__":
    main()
